import {KEY,normalizeJob,tailor,safeURL} from './core.js';
const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let resumeJobId="";let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||!Array.isArray(state.jobs))state={profile:{},jobs:[],resumes:{}};state.profile ||= {};state.resumes ||= {};
document.documentElement.dataset.careerpilot='1';
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Storage is full or unavailable. Export a backup before continuing.');return false}};
const toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)};
const download=(name,text,type='application/json')=>{const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
const heading=(eyebrow,title,desc,action='')=>`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="muted">${desc}</p></div>${action}</div>`;
const addButton='<button class="primary" data-action="add">＋ Add a job</button>';
const card=(j,i=0)=>`<article class="job-card"><div class="job-top"><span class="company-icon ${['','blue','sand'][i%3]}">${escape(j.company[0]?.toUpperCase()||'J')}</span><span class="tag">${escape(j.status)}</span></div><h3>${escape(j.title)}</h3><div class="company-line">${escape(j.company)} · ${escape(j.location)}</div><div class="job-meta"><span>${j.url?escape(new URL(j.url).hostname):'Manually added'}</span><span>${new Date(j.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span></div><div class="job-bottom"><span>Make your next move</span><button class="text-button" data-detail="${escape(j.id)}">View opportunity ↗</button></div></article>`;
function jobs(){return heading('A NEW CHAPTER, ON YOUR TERMS','Your next move starts here.','Find your focus. Make every application count.',addButton)+`<section class="hero"><div><span class="eyebrow">LESS BUSYWORK. MORE POSSIBILITY.</span><h2>A great opportunity deserves<br>a resume that fits.</h2><p>Save the roles that excite you. Bring your experience into focus with a resume tailored to each one.</p><a href="#resumes" class="primary">Open resume studio <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="paper"><i></i><i></i><i></i><i></i><i></i></div><span class="floating-star">✧</span></div></section><section class="stats"><div class="stat"><div><small>Saved opportunities</small><strong>${state.jobs.length.toString().padStart(2,'0')}</strong></div><span class="stat-symbol">▦</span></div><div class="stat"><div><small>Resumes prepared</small><strong>${Object.keys(state.resumes).length.toString().padStart(2,'0')}</strong></div><span class="stat-symbol">▤</span></div><div class="stat"><div><small>Applications sent</small><strong>${state.jobs.filter(j=>j.status==='Applied').length.toString().padStart(2,'0')}</strong></div><span class="stat-symbol">↗</span></div></section><div class="toolbar"><h2>Your opportunities <span class="muted">(${state.jobs.length})</span></h2><input class="search" id="search" aria-label="Search jobs" placeholder="⌕  Search title or company"><select id="status-filter" aria-label="Filter by status"><option>All statuses</option><option>Saved</option><option>Applied</option><option>Interview</option></select><label class="secondary file-label">Import job<input type="file" id="import-job" accept="application/json,.json"></label></div><p class="section-note">Your curated shortlist · Add jobs manually or capture them with the browser extension.</p><div class="jobs-grid" id="jobs-list">${jobList(state.jobs)}</div><p class="footer-note">Built for your next chapter. One thoughtful application at a time.</p>`}
function jobList(list){return list.length?list.map(card).join(''):'<div class="empty"><h3>Your next opportunity belongs here.</h3><p>Add a job to start building your shortlist.</p><button class="secondary" data-action="add">＋ Add your first job</button> <button class="ghost" data-action="demo">Explore with sample jobs</button></div>'}
function profile(){const p=state.profile;return heading('THE FOUNDATION','Tell your story.','One profile to power your resumes and applications.')+`<div class="panel"><form id="profile-form"><div class="two-col">${[['fullName','Full name','text'],['email','Email address','email'],['phone','Phone number','tel'],['location','Location','text'],['linkedin','LinkedIn URL','url'],['website','Portfolio / website','url']].map(([k,label,type])=>`<label>${label}<input name="${k}" type="${type}" value="${escape(p[k])}" ${k==='fullName'?'required':''}></label>`).join('')}</div><label>Skills <span class="muted">· separate with commas</span><input name="skills" value="${escape(p.skills)}" placeholder="JavaScript, Project management, Figma..."></label><label>Your experience and qualifications<textarea name="resume" rows="12" placeholder="Paste your existing resume text. Keep each accomplishment or experience block on its own line." required>${escape(p.resume)}</textarea></label><label class="secondary file-label">Import resume text (.txt)<input id="import-resume" type="file" accept="text/plain,.txt"></label><p class="note">Your profile stays in this browser. Resume tailoring prioritizes your existing experience and never adds qualifications. The extension copies this profile only when you click Sync on this workspace.</p><button class="primary">Save profile ↗</button> <button type="button" class="ghost" data-action="backup">Export workspace backup</button></form></div>`}
function studio(){return heading('MAKE YOUR EXPERIENCE COUNT','Resume studio','The right experience, brought to the front.')+`<div class="studio"><section class="panel"><h3>Choose your opportunity</h3><label>Saved job<select id="resume-job"><option value="">Select a job...</option>${state.jobs.map(j=>`<option value="${j.id}">${escape(j.title)} · ${escape(j.company)}</option>`).join('')}</select></label><button class="primary" id="tailor">Tailor my resume ✧</button><div id="skill-results"></div><p class="note">This sprint uses skill matching to prioritize your original resume lines. Review formatting and facts before downloading. Generative AI rewriting is planned for a later integration.</p><a href="#profile" class="text-button">Edit your base resume ↗</a></section><section><div class="resume-paper"><span class="eyebrow">YOUR RESUME · EDITABLE DRAFT</span><textarea id="resume-output" aria-label="Resume draft" placeholder="Your tailored resume will appear here. First, add your profile and choose a job."></textarea><div class="print-resume" id="print-resume"></div></div><div class="actions"><button class="secondary" id="download-resume">↓ Download .txt</button><button class="secondary" id="print">Print / Save as PDF</button><button class="primary" id="save-resume">Save draft</button></div></section></div>`}
function tracker(){return heading('ONE PLACE, EVERY NEXT STEP','Keep your momentum.','Track the opportunities you care about.',addButton)+`<div class="board">${['Saved','Applied','Interview'].map(status=>`<section class="board-column"><h3>${status} <span class="muted"> · ${state.jobs.filter(j=>j.status===status).length}</span></h3>${state.jobs.filter(j=>j.status===status).map(card).join('')||'<p class="muted">No opportunities here yet.</p>'}</section>`).join('')}</div>`}
function extension(){return heading('TAKE YOUR WORKSPACE WITH YOU','Meet your browser copilot.','Capture a job. Prepare your resume. Fill with confidence.')+`<section class="hero"><div><span class="eyebrow">CHROME EXTENSION · SPRINT ONE</span><h2>A simpler path from<br>job posting to application.</h2><p>Capture the page you’re viewing and preview recognized application fields before filling them.</p><a class="primary" href="careerpilot-extension.zip" download>↓ Download extension</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="paper"><i></i><i></i><i></i><i></i></div><span class="floating-star">↗</span></div></section><div class="panel steps"><div class="step"><div><strong>Install the unpacked extension</strong><p>Download and unzip the extension. Open <code>chrome://extensions</code>, turn on Developer mode, choose “Load unpacked”, and select the extracted extension folder.</p></div></div><div class="step"><div><strong>Connect your profile</strong><p>Save your profile in this workspace. While viewing this page, open the extension and click “Sync workspace”. Repeat Sync after changing your profile or capturing new jobs.</p></div></div><div class="step"><div><strong>Capture an opportunity</strong><p>Open a job posting, open the extension, and choose “Capture job”. Review its title, company, location, and description before saving. Return here and Sync to import saved jobs.</p></div></div><div class="step"><div><strong>Review, then autofill</strong><p>On an application page, click “Preview autofill”. Check the field mapping, then fill empty fields. Attach your downloaded resume yourself and review the application before submitting.</p></div></div></div><p class="note">Initial coverage: JobPosting structured data and common job-page layouts; standard text inputs, textareas and select fields. Custom widgets, nested frames, multi-step flows, and automatic file uploads need site-specific adapters. No automatic submission.</p>`}
function render(){let view=location.hash.slice(1)||'jobs';if(!['jobs','profile','resumes','tracker','extension'].includes(view))view='jobs';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.view===view));$('#view').innerHTML=({jobs,profile,resumes:studio,tracker,extension}[view])();$('#nav-count').textContent=state.jobs.length;$('#sidebar-name').textContent=state.profile.fullName||'Your workspace';bind(view);if(view==='resumes'&&resumeJobId){$('#resume-job').value=resumeJobId;$('#resume-job').dispatchEvent(new Event('change'))}}
function bind(view){if(view==='jobs'){const filter=()=>{$('#jobs-list').innerHTML=jobList(state.jobs.filter(j=>(j.title+' '+j.company).toLowerCase().includes($('#search').value.toLowerCase())&&($('#status-filter').value==='All statuses'||j.status===$('#status-filter').value)))};$('#search').oninput=filter;$('#status-filter').onchange=filter;$('#import-job').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('Choose a job file under 100 KB.');addJob(JSON.parse(await f.text()))}catch(err){toast(err.message)}}}
if(view==='profile'){$('#profile-form').onsubmit=e=>{e.preventDefault();state.profile=Object.fromEntries(new FormData(e.target));if(persist()){toast('Profile saved. Sync the extension to update it.');render()}};$('#import-resume').onchange=async e=>{const f=e.target.files[0];if(f&&f.size<200000)$('#profile-form textarea').value=await f.text();else toast('Choose a .txt resume under 200 KB.')}}
if(view==='resumes'){$('#resume-job').onchange=()=>{resumeJobId=$('#resume-job').value;$('#resume-output').value=state.resumes[$('#resume-job').value]?.text||'';$('#skill-results').innerHTML=''};$('#tailor').onclick=()=>{const j=state.jobs.find(j=>j.id===$('#resume-job').value);if(!j)return toast('Choose a saved job first.');if(!state.profile.resume)return toast('Add your experience in My profile first.');const r=tailor(state.profile,j);$('#resume-output').value=r.text;$('#skill-results').innerHTML=`<h3>${r.matched.length} matching skills</h3><div class="chips">${r.matched.map(s=>`<span>${escape(s)}</span>`).join('')||'<p class="muted">No exact skill matches. Your experience is preserved.</p>'}</div>`};$('#save-resume').onclick=()=>{const id=$('#resume-job').value,text=$('#resume-output').value;if(!id||!text.trim())return toast('Choose a job and create a draft first.');state.resumes[id]={text,updatedAt:new Date().toISOString()};if(persist())toast('Resume draft saved.')};$('#download-resume').onclick=()=>{if(!$('#resume-output').value.trim())return toast('Create a resume draft first.');download('tailored-resume.txt',$('#resume-output').value,'text/plain')};$('#print').onclick=()=>{if(!$('#resume-output').value.trim())return toast('Create a resume draft first.');$('#print-resume').textContent=$('#resume-output').value;window.print()}}
}
function addJob(raw){try{const job=normalizeJob(raw);if(job.url&&state.jobs.some(j=>j.url===job.url))return toast('This job is already saved.');state.jobs.unshift(job);if(persist()){render();toast('Opportunity saved.')}}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-detail],.close-dialog');if(!b)return;if(b.classList.contains('close-dialog'))return b.closest('dialog').close();if(b.dataset.detail){const j=state.jobs.find(j=>j.id===b.dataset.detail);if(!j)return;$('#detail').innerHTML=`<div class="dialog-heading"><span class="eyebrow">OPPORTUNITY DETAILS</span><button class="icon-button close-dialog" aria-label="Close">×</button></div><h2>${escape(j.title)}</h2><p class="muted">${escape(j.company)} · ${escape(j.location)}</p><pre>${escape(j.description)}</pre><label>Application status<select id="job-status">${['Saved','Applied','Interview'].map(s=>`<option ${j.status===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="actions">${j.url?`<a href="${escape(safeURL(j.url))}" target="_blank" rel="noopener noreferrer" class="primary">Open job ↗</a>`:''}<button class="secondary" id="detail-resume">Tailor resume</button><button class="ghost danger" id="delete-job">Delete job</button></div>`;$('#job-status').onchange=e=>{j.status=e.target.value;persist();render()};$('#detail-resume').onclick=()=>{$('#detail-dialog').close();resumeJobId=j.id;if(location.hash==='#resumes')render();else location.hash='resumes'};$('#delete-job').onclick=()=>{if(!confirm('Delete this job and its saved resume draft?'))return;state.jobs=state.jobs.filter(x=>x.id!==j.id);delete state.resumes[j.id];persist();$('#detail-dialog').close();render()};$('#detail-dialog').showModal();return}
if(b.dataset.action==='add')$('#job-dialog').showModal();if(b.dataset.action==='backup')download('careerpilot-backup.json',JSON.stringify(state,null,2));if(b.dataset.action==='demo'){const samples=[{title:'Senior Product Designer',company:'Northstar Studio',location:'Remote · United States',description:'DEMO OPPORTUNITY — not a live listing. Design thoughtful digital products with Figma, user research, prototyping and accessible design. Collaborate with product management and engineering.'},{title:'Frontend Engineer',company:'Forma',location:'Austin, TX · Hybrid',description:'DEMO OPPORTUNITY — not a live listing. Build accessible web experiences using JavaScript, React, CSS and TypeScript. Collaborate with designers and ship tested interfaces.'},{title:'Product Manager',company:'Evergreen',location:'Remote',description:'DEMO OPPORTUNITY — not a live listing. Own product strategy, stakeholder communication, project management and analytics. Turn customer research into clear priorities.'}];samples.forEach(j=>{const n=normalizeJob(j);n.company+=' (Sample)';state.jobs.push(n)});persist();render()}});
$('#job-form').onsubmit=e=>{e.preventDefault();addJob(Object.fromEntries(new FormData(e.target)));$('#job-dialog').close();e.target.reset()};
window.addEventListener('hashchange',render);window.addEventListener('storage',e=>{if(e.key===KEY)location.reload()});render();
